// 1. Adiabatic temperature rise from volume compression
val temperatureK = if (isAdiabatic) {
    t0K * (1.0f / volumeFraction).pow(gamma - 1f)
} else t0K

// 2. Pressure calculation along adiabatic vs isothermal path
val pressureAtm = if (isAdiabatic) {
    p0Atm * (1.0f / volumeFraction).pow(gamma)
} else p0Atm / volumeFraction

// 3. Mechanical work performed on the gas during compression
val cvJoulePerMolK = 8.314f / (gamma - 1f)
val workJoules = if (isAdiabatic) {
    cvJoulePerMolK * (temperatureK - t0K)
} else 8.314f * t0K * ln(1.0f / volumeFraction)
